export class Grid {
  /** @param {[number,number,number]} size */
  constructor(size, { dataVersion = DATA_VERSIONS["1.21.4"], entities = null } = {}) {
    this.size = [...size];
    this.dataVersion = dataVersion;
    this.entities = entities;                     // typed NBT list, passed through untouched
    /** @type {Map<string, {pos:number[], block:string, state?:Record<string,string>, nbt?:object}>} */
    this.cells = new Map();
  }

  inBounds(x, y, z) {
    return x >= 0 && y >= 0 && z >= 0 && x < this.size[0] && y < this.size[1] && z < this.size[2];
  }

  /** Set one block (state values become strings, as in NBT). Grows nothing: out of bounds throws. */
  set(x, y, z, block, state, nbt) {
    if (!this.inBounds(x, y, z)) throw new Error(`set out of bounds: ${x},${y},${z} (size ${this.size})`);
    const s = state && Object.keys(state).length
      ? Object.fromEntries(Object.entries(state).map(([k, v]) => [k, String(v)])) : undefined;
    this.cells.set(key(x, y, z), { pos: [x, y, z], block: ns(block), ...(s ? { state: s } : {}), ...(nbt ? { nbt } : {}) });
    return this;
  }

  get(x, y, z) { return this.cells.get(key(x, y, z)); }
  blockAt(x, y, z) { return this.get(x, y, z)?.block ?? "minecraft:air"; }
  isAir(x, y, z) { return AIRS.has(this.blockAt(x, y, z)); }
  unset(x, y, z) { this.cells.delete(key(x, y, z)); return this; }

